"use strict";
(()=>{const body=document.body;let theme;try{theme=localStorage.getItem('enlighten-display')}catch{}if(theme==='light')body.classList.add('light-display');const themeButtons=document.querySelectorAll('.theme-toggle');function themeLabel(){themeButtons.forEach(b=>b.setAttribute('aria-label',body.classList.contains('light-display')?'Switch to dark display':'Switch to light display'))}themeLabel();themeButtons.forEach(b=>b.addEventListener('click',()=>{body.classList.toggle('light-display');try{localStorage.setItem('enlighten-display',body.classList.contains('light-display')?'light':'dark')}catch{}themeLabel()}));const toggle=document.querySelector('.editorial-menu-toggle'),menu=document.querySelector('.editorial-menu');function close(){if(!menu)return;menu.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.textContent='Menu'}toggle?.addEventListener('click',()=>{const open=menu.hidden;menu.hidden=!open;toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?'Close':'Menu'});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu&&!menu.hidden){close();toggle.focus()}});document.addEventListener('click',e=>{if(menu&&!menu.hidden&&!menu.contains(e.target)&&!toggle.contains(e.target))close()});const cards=[...document.querySelectorAll('.project-card')],filters=[...document.querySelectorAll('[data-filter]')],search=document.querySelector('.search-label input'),empty=document.querySelector('.no-results');let category='All';function filter(){let count=0;cards.forEach(c=>{c.hidden=!(category==='All'||c.dataset.category===category)||!c.dataset.title.toLowerCase().includes((search?.value||'').toLowerCase());if(!c.hidden)count++});if(empty)empty.hidden=count>0}filters.forEach(b=>b.addEventListener('click',()=>{category=b.dataset.filter;filters.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));filter()}));search?.addEventListener('input',filter);const dialog=document.querySelector('.project-lightbox');let selected=0;function display(index){const visible=cards.filter(c=>!c.hidden);if(!visible.length)return;selected=(index+visible.length)%visible.length;const c=visible[selected],img=dialog.querySelector('img');img.src=c.dataset.image;img.alt=c.dataset.alt;dialog.querySelector('.lightbox-title').textContent=c.dataset.title}cards.forEach(c=>c.addEventListener('click',()=>{display(cards.filter(x=>!x.hidden).indexOf(c));dialog.showModal();body.style.overflow='hidden'}));dialog?.querySelector('.lightbox-close').addEventListener('click',()=>dialog.close());dialog?.addEventListener('close',()=>body.style.overflow='');dialog?.querySelector('.lightbox-previous').addEventListener('click',()=>display(selected-1));dialog?.querySelector('.lightbox-next').addEventListener('click',()=>display(selected+1));dialog?.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();display(selected+1)}if(e.key==='ArrowLeft'){e.preventDefault();display(selected-1)}})})();